/**
 * TypeScript client generation.
 *
 * Produces a dependency-free client: plain `fetch`, real types, one method per
 * observed operation. The generated file compiles on its own and is meant to be
 * committed or dropped into a project.
 */

import type { Cluster } from './har.ts';
import { hasRequestBody, queryParamNames } from './har.ts';
import { inferFromSamples } from './infer.ts';
import { isObject, pascalCase } from './util.ts';

function tsType(schema: any, depth = 0): string {
  if (!schema || typeof schema !== 'object') return 'unknown';

  if (Array.isArray(schema.enum) && schema.enum.length) {
    return schema.enum.map((v) => JSON.stringify(v)).join(' | ');
  }

  const type = schema.type;
  let base: string;

  if (Array.isArray(type)) {
    base = type.map((t) => tsType({ ...schema, type: t, nullable: false }, depth)).join(' | ');
  } else if (type === 'object') {
    const properties = schema.properties ?? {};
    const required = new Set<string>(schema.required ?? []);
    const keys = Object.keys(properties);
    if (!keys.length) {
      base = 'Record<string, unknown>';
    } else {
      const pad = '  '.repeat(depth + 1);
      const lines = keys.map((key) => {
        const safe = /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key) ? key : JSON.stringify(key);
        const optional = required.has(key) ? '' : '?';
        return `${pad}${safe}${optional}: ${tsType(properties[key], depth + 1)};`;
      });
      base = `{\n${lines.join('\n')}\n${'  '.repeat(depth)}}`;
    }
  } else if (type === 'array') {
    const inner = tsType(schema.items ?? {}, depth);
    base = /[|&]/.test(inner) ? `Array<${inner}>` : `${inner}[]`;
  } else if (type === 'integer' || type === 'number') {
    base = 'number';
  } else if (type === 'boolean') {
    base = 'boolean';
  } else if (type === 'string') {
    base = 'string';
  } else {
    base = 'unknown';
  }

  if (schema.nullable && !base.endsWith('| null')) base = `${base} | null`;
  return base;
}

/**
 * `/api/v1/users/{id}` → `["get", "Users", "ById"]`. Dropping the `api` and
 * version prefixes keeps generated method names readable (`getUsersById`
 * instead of `getApiV1UsersById`).
 */
function nameParts(cluster: Cluster): string[] {
  const parts = cluster.template
    .split('/')
    .filter(Boolean)
    .filter((segment) => !/^api$/i.test(segment) && !/^v\d+$/i.test(segment))
    .map((segment) => {
      const param = segment.match(/^\{(.+)\}$/);
      return param ? `By${pascalCase(param[1])}` : pascalCase(segment);
    });
  return [cluster.method.toLowerCase(), ...parts];
}

function uniqueName(base: string, used: Set<string>): string {
  if (!used.has(base)) {
    used.add(base);
    return base;
  }
  let counter = 2;
  while (used.has(`${base}${counter}`)) counter += 1;
  const name = `${base}${counter}`;
  used.add(name);
  return name;
}

function operationName(cluster: Cluster, used: Set<string>): string {
  const name = pascalCase(nameParts(cluster).join(' '));
  return uniqueName(name.charAt(0).toLowerCase() + name.slice(1), used);
}

function typeName(cluster: Cluster, suffix: string): string {
  return pascalCase([...nameParts(cluster), suffix].join(' '));
}

function successSample(cluster: Cluster): any[] {
  const ok = cluster.entries.filter((e) => e.status >= 200 && e.status < 300 && e.resBody !== undefined);
  const source = ok.length ? ok : cluster.entries.filter((e) => e.resBody !== undefined);
  return source.map((e) => e.resBody).filter((v) => isObject(v) || Array.isArray(v));
}

export interface ClientOptions {
  className?: string;
  baseUrl?: string;
}

export function buildClient(clusters: Cluster[], origin: string, options: ClientOptions = {}): string {
  const className = options.className ?? 'ApiClient';
  const lines: string[] = [];

  lines.push('/**');
  lines.push(' * Generated by harspec from recorded HTTP traffic.');
  lines.push(' * Every method below corresponds to a request observed in the capture.');
  lines.push(' * Zero dependencies: uses the global fetch available in Node 18+, Deno, Bun and browsers.');
  lines.push(' */');
  lines.push('');
  lines.push('export interface ClientOptions {');
  lines.push('  /** Base URL of the API. Defaults to the origin seen in the capture. */');
  lines.push('  baseUrl?: string;');
  lines.push('  /** Sent as `Authorization: Bearer <token>` when provided. */');
  lines.push('  token?: string;');
  lines.push('  /** Extra headers merged into every request. */');
  lines.push('  headers?: Record<string, string>;');
  lines.push('}');
  lines.push('');
  lines.push('export class ApiError extends Error {');
  lines.push('  readonly status: number;');
  lines.push('  readonly body: string;');
  lines.push('  readonly url: string;');
  lines.push('');
  lines.push('  constructor(status: number, body: string, url: string) {');
  lines.push('    super(`HTTP ${status} from ${url}`);');
  lines.push('    this.name = "ApiError";');
  lines.push('    this.status = status;');
  lines.push('    this.body = body;');
  lines.push('    this.url = url;');
  lines.push('  }');
  lines.push('}');
  lines.push('');

  const emittedTypes = new Set<string>();
  const usedMethodNames = new Set<string>();
  const methodBlocks: string[] = [];

  for (const cluster of clusters) {
    const name = operationName(cluster, usedMethodNames);
    const pathParams = cluster.pathParams;
    const queryParams = queryParamNames(cluster);
    const args: string[] = [];
    const argDocs: string[] = [];

    for (const param of pathParams) {
      args.push(`${param}: string | number`);
      argDocs.push(`@param ${param} - path parameter`);
    }

    if (queryParams.length) {
      const shape = queryParams
        .map((param) => {
          const values = cluster.entries.map((e) => e.query[param]).filter((v) => v !== undefined);
          const numeric = values.length > 0 && values.every((v) => /^-?\d+$/.test(v));
          return `    ${param}?: ${numeric ? 'number' : 'string'};`;
        })
        .join('\n');
      args.push(`params?: {\n${shape}\n  }`);
      argDocs.push('@param params - query parameters');
    }

    let requestTypeName: string | undefined;
    if (hasRequestBody(cluster)) {
      const samples = cluster.entries
        .map((e) => e.reqBody)
        .filter((v) => isObject(v) || Array.isArray(v));
      if (samples.length) {
        requestTypeName = typeName(cluster, 'Request');
        if (!emittedTypes.has(requestTypeName)) {
          emittedTypes.add(requestTypeName);
          lines.push(`export type ${requestTypeName} = ${tsType(inferFromSamples(samples), 0)};`);
          lines.push('');
        }
        args.push(`body: ${requestTypeName}`);
        argDocs.push(`@param body - request body`);
      }
    }

    const samples = successSample(cluster);
    let returnType = 'unknown';
    if (samples.length) {
      const responseTypeName = typeName(cluster, 'Response');
      if (!emittedTypes.has(responseTypeName)) {
        emittedTypes.add(responseTypeName);
        lines.push(`export type ${responseTypeName} = ${tsType(inferFromSamples(samples), 0)};`);
        lines.push('');
      }
      returnType = responseTypeName;
    }

    const pathExpression = buildPathExpression(cluster);
    const queryBlock = queryParams.length
      ? [
          '    const query = new URLSearchParams();',
          `    for (const [key, value] of Object.entries(params ?? {})) {`,
          '      if (value !== undefined) query.set(key, String(value));',
          '    }',
          '    const search = query.toString();',
          '    const url = this.baseUrl + path + (search ? `?${search}` : "");',
        ]
      : ['    const url = this.baseUrl + path;'];

    methodBlocks.push(
      [
        '  /**',
        `   * ${cluster.method} ${cluster.template}`,
        ...argDocs.map((d) => `   * ${d}`),
        '   */',
        `  async ${name}(${args.join(', ')}): Promise<${returnType}> {`,
        `    const path = ${pathExpression};`,
        ...queryBlock,
        '    const response = await this.fetch(url, {',
        '      method: ' + JSON.stringify(cluster.method) + ',',
        ...(requestTypeName
          ? [
              '      headers: { "Content-Type": "application/json" },',
              '      body: JSON.stringify(body),',
            ]
          : []),
        '    });',
        '    const text = await response.text();',
        '    if (!response.ok) throw new ApiError(response.status, text, url);',
        '    if (!text) return undefined as unknown as ' + returnType + ';',
        '    return JSON.parse(text) as ' + returnType + ';',
        '  }',
        '',
      ].join('\n'),
    );
  }

  lines.push(`export class ${className} {`);
  lines.push('  readonly baseUrl: string;');
  lines.push('  private readonly token?: string;');
  lines.push('  private readonly extraHeaders: Record<string, string>;');
  lines.push('');
  lines.push('  constructor(options: ClientOptions = {}) {');
  lines.push(`    this.baseUrl = (options.baseUrl ?? ${JSON.stringify(origin)}).replace(/\\/$/, "");`);
  lines.push('    this.token = options.token;');
  lines.push('    this.extraHeaders = options.headers ?? {};');
  lines.push('  }');
  lines.push('');
  lines.push('  private async fetch(url: string, init: RequestInit = {}): Promise<Response> {');
  lines.push('    const headers: Record<string, string> = { ...this.extraHeaders, ...(init.headers as any) };');
  lines.push('    if (this.token) headers.Authorization = `Bearer ${this.token}`;');
  lines.push('    return fetch(url, { ...init, headers });');
  lines.push('  }');
  lines.push('');
  lines.push(...methodBlocks);
  lines.push('}');
  lines.push('');

  return lines.join('\n');
}

function buildPathExpression(cluster: Cluster): string {
  return `\`${cluster.template.replace(/\{(.+?)\}/g, '${encodeURIComponent(String($1))}')}\``;
}
